target.css:
:root {
  --bg-card: #faf6ee;
  --border-card: #c8b99a;
  --header-bg: #3d2f1f;
  --header-text: #f0e6d0;
  --accent-gold: #b8860b;
  --accent-lavender: #7b6b9e;
  --stem-color: #5a7a3a;
  --leaf-color: #6a8c48;
  --flower-color: #9b7bb8;
  --petal-color: #c4a0d8;
  --label-color: #7a6a52;
  --text-dark: #2e2010;
  --text-mid: #5c4a30;
  --divider: #ddd0b8;
  --badge-bg: #eae0cc;
  --verified-bg: #4a3a6a;
  --verified-text: #e8d8f8;
  --footer-bg: #ede4d4;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.herbarium-card {
  background: var(--bg-card);
  border: 2px solid var(--border-card);
  border-radius: 6px;
  width: 480px;
  max-width: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.collection-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--header-text);
}

.accession-num {
  font-size: 11px;
  color: var(--accent-gold);
  font-weight: 600;
  letter-spacing: 0.05em;
}

.specimen-area {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.specimen-figure {
  width: 140px;
  min-width: 140px;
  background: var(--badge-bg);
  border-right: 1px solid var(--divider);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px 8px 8px;
  margin: 0;
  gap: 6px;
}

.plant-silhouette {
  position: relative;
  width: 70px;
  height: 110px;
}

.stem {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 4px;
  height: 90px;
  background: var(--stem-color);
  border-radius: 2px;
}

.leaf {
  position: absolute;
  background: var(--leaf-color);
  border-radius: 50% 50% 50% 0;
}

.leaf-left {
  transform-origin: bottom right;
  transform: rotate(-40deg);
  right: 50%;
}

.leaf-right {
  transform-origin: bottom left;
  transform: rotate(40deg);
  left: 50%;
  border-radius: 50% 50% 0 50%;
}

.leaf-lg {
  width: 26px;
  height: 14px;
  bottom: 54px;
}

.leaf-md {
  width: 20px;
  height: 11px;
  bottom: 68px;
}

.leaf-sm {
  width: 14px;
  height: 8px;
  bottom: 78px;
}

.flower-head {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 14px;
  background: var(--flower-color);
  border-radius: 50%;
  z-index: 2;
}

.petal {
  position: absolute;
  width: 10px;
  height: 16px;
  background: var(--petal-color);
  border-radius: 50%;
  top: 7px;
  left: 50%;
  transform-origin: bottom center;
  z-index: 1;
}

.p1 { transform: translateX(-50%) rotate(0deg) translateY(-12px); }
.p2 { transform: translateX(-50%) rotate(90deg) translateY(-12px); }
.p3 { transform: translateX(-50%) rotate(180deg) translateY(-12px); }
.p4 { transform: translateX(-50%) rotate(270deg) translateY(-12px); }

.specimen-caption {
  font-size: 10px;
  color: var(--label-color);
  letter-spacing: 0.08em;
  font-style: italic;
}

.specimen-info {
  flex: 1;
  padding: 14px 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.species-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0;
  font-style: italic;
  line-height: 1.2;
}

.common-name {
  font-size: 12px;
  color: var(--accent-lavender);
  margin: 0;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.taxonomy-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--divider);
  border-bottom: 1px solid var(--divider);
  padding: 6px 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.taxonomy-list li {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
}

.tax-label {
  color: var(--label-color);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.tax-value {
  color: var(--text-mid);
  font-size: 12px;
}

.collection-meta {
  display: flex;
  gap: 12px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.meta-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--label-color);
}

.meta-value {
  font-size: 11px;
  color: var(--text-dark);
  font-weight: 600;
}

.status-tag {
  display: inline-flex;
  align-self: flex-start;
  background: var(--verified-bg);
  color: var(--verified-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 10px;
  border-radius: 12px;
  text-transform: uppercase;
}

.card-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--divider);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 16px;
}

.institution {
  font-size: 10px;
  color: var(--text-mid);
  font-style: italic;
  letter-spacing: 0.04em;
}

.condition-badge {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-gold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

